                  </Button>
                  <Button onClick={() => navigate("/app/waitlist")}>
                    View Waitlist
                  </Button>
                  <Button onClick={() => navigate("/app/delivery-rules")}>
                    Manage Delivery Rules
                  </Button>
                </InlineStack>
              </BlockStack>
            </Card>
          </Layout.Section>

        </Layout>
