 633→            </Banner>
 634→          </Layout.Section>
 635→        </Layout>
 636→      </Page>
 637→    );
 638→  }
 639→
 640→  const statusOptions = [
 641→    { label: "Waiting", value: "waiting" },
 642→    { label: "Accepted", value: "accepted" },
 643→    { label: "Rejected", value: "rejected" },
 644→    { label: "Notified", value: "notified" },
 645→    { label: "Converted", value: "converted" },
 646→  ];
 647→
 648→  const filterOptions = [
 649→    { label: "All", value: "all" },
 650→    { label: "Waiting", value: "waiting" },
 651→    { label: "Accepted", value: "accepted" },
 652→    { label: "Rejected", value: "rejected" },
 653→    { label: "Notified", value: "notified" },
 654→    { label: "Converted", value: "converted" },
 655→  ];
 656→
 657→  const formatDate = (d: string | Date) => {
