 659→    return date.toLocaleDateString("en-US", {
 660→      month: "short",
 661→      day: "numeric",
 662→      year: "numeric",
 663→    });
 664→  };
 665→
 666→  const bulkActions = [
 667→    {
 668→      content: "Accept Selected",
 669→      onAction: () => handleBulkAction("accept"),
 670→    },
 671→    {
 672→      content: "Reject Selected",
 673→      onAction: () => handleBulkAction("reject"),
 674→    },
 675→    {
 676→      content: "Delete Selected",
 677→      onAction: () => handleBulkAction("delete"),
 678→      destructive: true,
 679→    },
