 681→
 682→  const promotedBulkActions = [
 683→    {
 684→      content: "Notify Selected",
 685→      onAction: () => handleBulkAction("notify"),
 686→    },
 687→  ];
 688→
 689→  return (
 690→    <Page
 691→      title="Customer Waitlist"
 692→      subtitle="Customers waiting for delivery availability in their area"
 693→      backAction={{ onAction: () => navigate("/app") }}
 694→      primaryAction={
 695→        isStarterPlan && stats.total >= limits.maxWaitlist
 696→          ? {
 697→              content: "Upgrade to Add More",
 698→              onAction: () => navigate("/app/pricing"),
 699→            }
 700→          : {
 701→              content: "Add Entry",
 702→              icon: PlusIcon,
 703→              onAction: () => setAddModalOpen(true),
 704→            }
 705→      }
 706→    >
 707→      <Box paddingBlockEnd="1600">
 708→      <Layout>
 709→        {/* Stats */}
