 682→
 683→  const filterOptions = [
 684→    { label: "All", value: "all" },
 685→    { label: "Waiting", value: "waiting" },
 686→    { label: "Accepted", value: "accepted" },
 687→    { label: "Rejected", value: "rejected" },
 688→    { label: "Notified", value: "notified" },
 689→    { label: "Converted", value: "converted" },
 690→  ];
 691→
 692→  const formatDate = (d: string | Date) => {
 693→    const date = new Date(d);
 694→    return date.toLocaleDateString("en-US", {
 695→      month: "short",
 696→      day: "numeric",
 697→      year: "numeric",
 698→    });
 699→  };
 700→
 701→  const bulkActions = [
 702→    {
 703→      content: "Accept Selected",
 704→      onAction: () => handleBulkAction("accept"),
 705→    },
 706→    {
 707→      content: "Reject Selected",
 708→      onAction: () => handleBulkAction("reject"),
 709→    },
