 711→      content: "Delete Selected",
 712→      onAction: () => handleBulkAction("delete"),
 713→      destructive: true,
 714→    },
 715→  ];
 716→
 717→  const promotedBulkActions = [
 718→    {
 719→      content: "Notify Selected",
 720→      onAction: () => handleBulkAction("notify"),
 721→    },
 722→  ];
 723→
 724→  return (
 725→    <Page
 726→      title="Customer Waitlist"
 727→      subtitle="Customers waiting for delivery availability in their area"
